            'Este é um lindo apartamento localizado a apenas 700 metros do Shopping Anália Franco, em um dos bairros mais prestigiados de São Paulo. Com uma planta de 39,07 m2, este apartamento recém-construído possui 2 quartos, banheiro e uma varanda com vista para o Shopping Anália Franco.

