Os moradores deste condomínio podem desfrutar de uma variedade de opções de lazer, como um salão de festas equipado com eletrodomésticos, uma piscina adulto e infantil, áreas de churrasqueira, academia e playground. O condomínio também possui portaria 24 horas e 2 elevadores por torre, garantindo a segurança e a comodidade dos moradores.

